  "bioavailability_prediction": "low",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C194", "C149", "C139", "C130", "C141", "C210", "C179", "C200", "C172", "C53", "C04", "C61"],
  "contradictory_card_ids": ["C214", "C164", "C199"],
  "prediction_basis_card_ids": ["C194", "C149", "C139", "C130", "C141", "C210", "C53", "C04", "C61"],
  "claims": [
    {
      "claim": "L5 C194 shows that EXP3174, the closest dianionic imidazole-carboxylate analog to the query, has Caco-2 permeability of only ~1 × 10⁻⁸ cm/s, affirmatively indicating very poor intestinal permeability for this scaffold.",
      "card_ids": ["C194"]
    },
    {
      "claim": "L4 C149/C139/C130/C141 show EXP3174 A→B permeability of 2.50 × 10⁻⁸ cm/s with high B→A permeability (25.6 × 10⁻⁸ cm/s), and A→B remains very low even with P-gp or BCRP inhibition, indicating low passive permeability rather than efflux-limited absorption alone.",
      "card_ids": ["C149", "C139", "C130", "C141"]
    },
    {
      "claim": "L5 C210/C179/C200 and C172 show that losartan, a less charged sartan analog, has A→B ~1.0 × 10⁻⁶ cm/s, B→A ~3.7 × 10⁻⁶ cm/s, and an efflux ratio of 3.7 that verapamil reduces to ~1.03; the query's dianionic dicarboxylate state and logD 0.56 make it no more permeable and potentially more absorption-limited.",
      "card_ids": ["C210", "C179", "C200", "C172"]
    },
    {
      "claim": "Direct low-F analogs remain relevant: azosemide human F ≈10–20.4% (C53, C04) and bumetanide rat intraduodenal F ≈15.8% (C61) support F < 20% for highly ionized carboxylate-containing drugs.",
      "card_ids": ["C53", "C04", "C61"]
    },
    {
      "claim": "Positive absorption records for olmesartan (C214, C164) and TAK-491 (C199) involve different acid/charge topologies or prodrug-related contexts and do not provide threshold-relevant F evidence for the query.",
      "card_ids": ["C214", "C164", "C199"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C194", "C210", "C179", "C200", "C172"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "No query-specific Caco-2/MDCK permeability, efflux, or intestinal metabolism data.",
    "No matched oral-versus-IV exposure, dose, formulation, or prandial condition for the query.",
    "EXP3174 is a metabolite analog and not identical to the query; transfer depends on structural analogy.",
    "Possible active uptake transporters, prodrug effects, or formulation effects for the query are not assessed.",
    "L5 intestinal-metabolism records do not include query-specific first-pass metabolism data."
  ],
  "decision_summary": "L5 strengthens the low prediction: the closest dianionic analog EXP3174 has very low Caco-2 permeability (~1 × 10⁻⁸ cm/s), and losartan shows P-gp-mediated efflux, while the query is a dianionic dicarboxylate with logD 0.56. Combined with direct low-F analogs azosemide and bumetanide rat data, F < 20% remains better supported; positive absorption records for olmesartan and TAK-491 are less transferable and lack threshold F evidence."
}

